        for line in block["lines"]:
            for span in line["spans"]:
                text = span["text"]
                bbox = span["bbox"]
                if 'Yueqian' in text and author_area_top is None:
                    author_area_top = bbox[1] - 2
                if 'Correspondence' in text or 'adobe.com' in text or '@duke.edu' in text:
